import pty, os, struct, fcntl, termios, time, signal

def pty_test(term, rows=24, cols=80):
    master, slave = pty.openpty()
    winsize = struct.pack("HHHH", rows, cols, 0, 0)
    try: fcntl.ioctl(slave, termios.TIOCSWINSZ, winsize)
    except: pass
    pid = os.fork()
    if pid==0:
        os.setsid()
        os.close(master)
        os.dup2(slave,0)
        os.dup2(slave,1)
        os.dup2(slave,2)
        os.close(slave)
        if term is None:
            os.environ.pop("TERM",None)
        else:
            os.environ["TERM"]=term
        os.execv("./executable", ["./executable"])
    else:
        os.close(slave)
        time.sleep(0.5)
        os.set_blocking(master, False)
        try:
            data = os.read(master, 8192)
            print(f"term={term!r} {rows}x{cols} => {data[:200]!r} len {len(data)}")
            if b"Too small" in data: print("  ->Too small")
            elif b"Cannot detect" in data: print("  ->Cannot")
            elif b"Failed" in data: print("  ->Failed")
            elif data.startswith(b"\x1b"): print("  ->TUI")
            else: print("  ->other")
        except Exception as e:
            print(f"err {e}")
        try: os.kill(pid, signal.SIGTERM); os.waitpid(pid,0)
        except: pass
        try: os.close(master)
        except: pass

for term in [None, "xterm", "unknown", "dumb", ""]:
    pty_test(term, 24,80)
    time.sleep(0.1)
PY
